import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';

/**
 * Only this shell is in the admin bundle. The workspace (every section) is a
 * lazy chunk, fetched the first time the page opens.
 */
export default class SurveyorPage extends ExtensionPage {
  oninit(vnode) {
    super.oninit(vnode);
    this.Workspace = null;
    import(/* webpackChunkName: 'admin/workspace/Workspace', webpackMode: 'lazy-once' */ './workspace/Workspace').then(module => {
      this.Workspace = module.default;
      m.redraw();
    });
  }
  sections(vnode) {
    const items = super.sections(vnode);
    const Workspace = this.Workspace;
    items.remove('permissions');
    items.remove('content');
    items.add('surveyor', m("div", {
      className: "ExtensionPage-settings SurveyorPage"
    }, m("div", {
      className: "container"
    }, Workspace ? m(Workspace, {
      page: this
    }) : m(LoadingIndicator, null))), 20);
    return items;
  }
}flarum.reg.addChunkModule('ernestdefoe-surveyor:admin/workspace/Workspace', '4', 'ernestdefoe-surveyor', 'admin/workspace/Workspace');